def calcul_nozero(dic1):
    sum=0
    for key in dic1:
        sum+=dic1[key]
    non_zero_cnt=0
    for key in dic1:
        if(key>0):
            non_zero_cnt+=dic1[key]
    ratio=non_zero_cnt/sum
    return ratio

def cal_key_space(lst1):
    r=1
    for dic1 in lst1:
       r*=calcul_nozero(dic1)
    print(np.log2(r))
    l_r=np.log2(r)
    return l_r 

